class A {
  n() {
    return this.x;
  }
}
class B extends A {
  n() {
    return super.n();
  }
}
const obj = { x: 4, n: B.prototype.n };
console.log(obj.n());

class MyArray extends Array {
  static get [Symbol.species]() {
    return Array;
  }
}
const mapped = new MyArray(1, 2).map((x) => x);
console.log(mapped instanceof MyArray ? 1 : 0);
console.log(mapped instanceof Array ? 1 : 0);

